  el: '#app',
  mixins: [helperMixin],
  components: {  SupplierItemNumberMap },
  data() {
    return {
      percent: CONSTANTS.percent,
      is_po_active: CONSTANTS.is_po_active,
      po_quantity_column: CONSTANTS.po_quantity_column,
      quantity_tolerance: CONSTANTS.quantity_tolerance,
      unit_price_tolerance: CONSTANTS.unit_price_tolerance,
      po_unit_tolerance_type: CONSTANTS.po_unit_tolerance_type,
      calculate_po_unit_price: CONSTANTS.CALCULATE_PO_UNIT_PRICE,
      consumed_po_line_status: CONSTANTS.CONSUMED_PO_LINE_STATUS,
      po_quantity_tolerance_type: CONSTANTS.po_quantity_tolerance_type,
      custom_range_for_po_tolerance: CONSTANTS.custom_range_for_po_tolerance,
      additional_range_for_po_tolerance:
        CONSTANTS.additional_range_for_po_tolerance,
      auto_check_for_po_update: CONSTANTS.auto_check_for_po_update,
      freight_unit_tolerance: CONSTANTS.freight_unit_tolerance,
      charges_unit_tolerance: CONSTANTS.charges_unit_tolerance,
      auto_update_po_data: CONSTANTS.auto_update_po_data,
      tax_unit_tolerance : CONSTANTS.tax_unit_tolerance,
      freight_tolerance : CONSTANTS.freight_tolerance,
      charges_tolerance : CONSTANTS.charges_tolerance,
      po_tolerance_type: preparePoToleranceTypeOptions(),
      po_match_server_side: CONSTANTS.PO_MATCH_SERVER_SIDE,
      tax_tolerance : CONSTANTS.tax_tolerance,
      PO_STATUSES: PO_STATUSES,
      po_status_in_docs: CONSTANTS.po_status_in_docs,
      disabled_po_status_options: [] as any,
      po_disabled_statuses_setting,
      po_table_in_layout_builder,
      export_non_matched_po_lines,
      searchValue: ref(''),
      ignore_already_matched_lines,
      allow_auto_export_for_non_matchable_po_lines,
      use_lines_net_amount_permission,
      auto_match_export_permission,
      po_line_permission_options: [] as any,
    };
  },
  watch: {
    loading_data: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }

        this.loadCustomList();
      },
    },
  },
  mounted: function () {
    this.initView();
    this.initLists();
    this.loadCustomList();
  },
  methods: {
    goHelp() {
      if (!getLink('update_documents_po')) {
        return;
      }
      window.open(getLink('update_documents_po'));
    },
    emitSearch() {
      const trime_value = this.searchValue.trim();
      this.$emit('onSearchValue', trime_value);
    },
    removeSpaces() {
      this.searchValue = this.searchValue.replace(/\s+/g, '');
    },

    initView() {
      this.preparePoMatchTypeList();

      const defaults = {
        [this.is_po_active]: false,
        [this.po_match_server_side]: false,
        [this.po_quantity_column]: 'received_quantity',
        [this.quantity_tolerance]: 1,
        [this.unit_price_tolerance]: 1,
        [this.po_unit_tolerance_type]: this.percent,
        [this.po_quantity_tolerance_type]: this.percent,
        [this.custom_range_for_po_tolerance]: false,
        [this.additional_range_for_po_tolerance]: false,
        [this.po_table_in_layout_builder]: false,
        [this.auto_check_for_po_update]: false,
        [this.consumed_po_line_status]: false,
        [this.calculate_po_unit_price]: false,
        [this.auto_update_po_data]: false,
        [this.po_status_in_doc]: false,
        [this.freight_tolerance]: 1,
        [this.charges_tolerance]: 1,
        [this.tax_tolerance]: 1,
        [this.charges_unit_tolerance]: this.percent,
        [this.freight_unit_tolerance]: this.percent,
        [this.tax_unit_tolerance]: this.percent,
        [this.export_non_matched_po_lines]: false,
        [this.ignore_already_matched_lines]: true,
        [this.allow_auto_export_for_non_matchable_po_lines]: false,
        [this.auto_match_export_permission]: PO_LINE_PERMISSION_ADMIN,
        [this.use_lines_net_amount_permission]: PO_LINE_PERMISSION_ADMIN,
      };

      for (const key in defaults) {
        if (!this.model[key]) {
          this.model[key] = defaults[key];
        }
      }
    },

    initLists() {
      this.disabled_po_status_options = [];
      for (const [key, item] of Object.entries(this.PO_STATUSES)) {
        this.disabled_po_status_options.push({
          label: this.$t(item.label),
          value: item.value,
        });
      }

      this.po_line_permission_options = [
        { label: this.$t('only_admin'), value: PO_LINE_PERMISSION_ADMIN },
        { label: this.$t('all_users'), value: PO_LINE_PERMISSION_ALL },
      ];
    },

    savePODisabledStatuses() {
      let status_str = '';
      this.selected_status.forEach((status: any) => {
        status_str += status.value + ',';
      });
      status_str = status_str.slice(0, -1);

      this.model[this.po_disabled_statuses_setting] = status_str;
      this.updateValue(this.po_disabled_statuses_setting, status_str);
      notify.success(this.$t('operation_sucessfull'));
    },

    loadCustomList() {
      this.selected_status = [];
      if (!this.model[this.po_disabled_statuses_setting]) {
        this.selected_status = [];
        return;
      }

      this.model[this.po_disabled_statuses_setting]
        .split(',')
        .forEach((status: any) => {
          let key = status;
          this.selected_status.push(
            Object.assign(
              {},
              {
                value: key,
                label: documentUtil.methods.getLabelTranslation(status),
              },
            ),
          );
        });
    },

    async updateValue(attribute_key: string, attribute_value: any) {
      try {
        this.loading_data = true;
        await this.setAttribute(attribute_key, attribute_value);
        this.model[attribute_key] = attribute_value;
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading_data = false;
      }
    },

    validateTolerance(
      attribute_key: string,
      attribute_value: any,
      sibling_attribute_unit: any,
    ) {
      if (
        (attribute_value < 1 || attribute_value > 100) &&
        this.model[sibling_attribute_unit] === this.percent
      ) {
        return;
      }
      this.updateValue(attribute_key, attribute_value);
    },

    updateToleranceTypeValue(
      attribute_key: string,
      attribute_value: any,
      sibling_attribute_key: any,
    ) {
      if (
        (this.model[sibling_attribute_key] < 1 ||
          this.model[sibling_attribute_key] > 100) &&
        attribute_value === this.percent
      ) {
        this.model[sibling_attribute_key] = 1;
      }
      this.updateValue(attribute_key, attribute_value);
      this.validateTolerance(
        sibling_attribute_key,
        this.model[sibling_attribute_key],
        attribute_value,
      );
    },

    preparePoMatchTypeList() {
      // values needs to be the exect keys of po table columns
      this.po_quantity_type_list = [
        {
          label: this.$t('quantity'),
          value: 'quantity',
        },
        {
          label: this.$t('received_quantity'),
          value: 'received_quantity',
        },
        {
          label: this.$t('received_delivery_open_quantity'),
          value: 'invoice_open_quantity',
        },
      ];
    },

    configurePOMatchingRules() {
      const doc_type = String(this.$route.params.doc_type || '');
      this.$router.push('/settings/po-match-rules/' + doc_type);
    },
  },
  setup() {
    const doc_attribute_store = useDocAttributesStore();
    const { model, loading_data } = storeToRefs(doc_attribute_store);
    const { setAttribute } = doc_attribute_store;

    return {
      setAttribute,
      model,
      loading_data,
      selected_status: ref([] as any),
      po_quantity_type_list: ref([] as any),
    };
  },
});
</script>

