<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import { docTypeApiService } from 'src/services';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import PO from 'src/pages/Settings/Components/DocTypes/PO.vue';
import { formBuilderApiService, decisionApiService } from 'src/services';
import { useDocAttributesStore, useDocExportStore } from 'src/store/main';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';
import {
  skip_table_validation,
  approve_before_export,
  approve_before_export_v2,
  custom_validation_rules_enabled,
  second_approval_before_export,
  layout_types,
  pdf_export_to_idm,
  pdf_template,
  approval_stamp,
  approval_history,
  CONSTANTS,
  isInvoice,
  doc_alternate_export_status,
  doc_alternate_export_setting,
  alternate_export_statuses_all,
  doc_alternate_export_export_config,
  xrechnung_validation_enabled,
  xrechnung_supplier_notification_enabled,
} from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin, displayFieldLabel],
  components: {
    Loader,
    PO,
    DocbitsAccordionPanel,
  },
  watch: {
    loading_data: {
      handler: function (newVal, oldVal) {
        if (newVal === true) {
          this.showLoading();
          return;
        }
        this.hideLoading();
        this.formatePreferenceData();
      },
    },
    processing: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }

        this.loadExportConfigurationsList();
      },
    },
    // Re-run the Quick Search deep link when only the query changes (the
    // Settings router-view key is stable, so the component is not remounted).
    '$route.query.open': function (val) {
      if (val === 'einvoice-validation') this.openEInvoiceFromDeepLink();
    },
  },
  computed: {
    // Layouts & Custom Validation Rules are still in beta and only surface
    // when the page is opened with ?beta=true (matches the ?debug=true /
    // ?auto_testing=true convention used elsewhere in the app).
    isBetaEnabled(): boolean {
      return this.$route.query.beta === 'true';
    },
  },
  data() {
    return {
      layout_types,
      pdf_template,
      approval_stamp,
      approval_history,
      pdf_export_to_idm,
      skip_table_validation,
      approve_before_export,
      approve_before_export_v2,
      custom_validation_rules_enabled,
      transformation_rules_enabled: CONSTANTS.TRANSFORMATION_RULES_ENABLED,
      layout_selection_rules_enabled: CONSTANTS.LAYOUT_SELECTION_RULES_ENABLED,
      second_approval_before_export,
      xrechnung_validation_enabled,
      xrechnung_supplier_notification_enabled,
      isInvoice: isInvoice,
      ai_system_prompt: CONSTANTS.AI_SYSTEM_PROMPT,
      export_pdf_format: CONSTANTS.export_pdf_format,
      ai_assistant_prompt: CONSTANTS.AI_ASSISTANT_PROMPT,
      duplicate_detection: CONSTANTS.DUPLICATE_DETECTION,
      duplicate_detection_fields: CONSTANTS.DUPLICATE_DETECTION_FIELDS,
      duplicate_invoice_detection: CONSTANTS.DUPLICATE_INVOICE_DETECTION,
      duplicate_detection_interval: CONSTANTS.DUPLICATE_DETECTION_INTERVAL,
      disallow_export_of_duplicates: CONSTANTS.DISALLOW_EXPORT_OF_DUPLICATES,
      allow_multiple_export_configurations: CONSTANTS.ALLOW_MULTIPLE_EXPORT_CONFIGURATIONS,
      ignore_tax_free_line : CONSTANTS.IGNORE_TAX_FREE_LINE,
      expandedSections: {
        purchaseOrder: true,
        manageLayouts: false,
        approvalRejection: false,
        vertexTaxVerification: false,
        customValidationRules: false,
        transformationRules: false,
        einvoiceValidation: false,
        tableExtraction: false,
        exportSetting: false,
        duplicateDetection: false,
      } as Record<string, boolean>,
      doc_alternate_export_setting,
      doc_alternate_export_status,
      doc_alternate_export_export_config,
      alternate_export_statuses_all,
      alternate_export_statuses_list: [] as any,
    };
  },
  mounted: async function () {
    await this.init();
    this.openEInvoiceFromDeepLink();
  },
  methods: {
    async init() {
        try {
          this.loading_data = true;
          this.doc_type_key = String(this.$route.params.doc_type || '');
          this.setDefaultValues();
          this.getDocumentFields();
          this.preparePdfExportTypeList();
          this.prepareDuplicateDetectionIntervalOptions();
          this.initAlternateExportStatuses();
          this.getExportConfigurations();
          await this.getDocTypeSettings();
        } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
        } finally {
          this.loading_data = false;
        }
    },

    // Deep link from global Quick Search (?open=einvoice-validation).
    // The Settings layout keeps a stable router-view key, so navigating
    // doc-type -> doc-type or re-triggering Quick Search reuses this same
    // component without remounting (mounted does not re-run). This runs from
    // both mounted and a watcher on $route.query.open, and reloads for the
    // target doc type first if the reused instance is showing another one.
    openEInvoiceFromDeepLink() {
      if (this.$route.query.open !== 'einvoice-validation') return;
      const targetType = String(this.$route.params.doc_type || '');
      if (targetType && targetType !== this.doc_type_key) {
        this.init().then(() => this.revealEInvoiceSection());
        return;
      }
      this.revealEInvoiceSection();
    },

    revealEInvoiceSection() {
      if (!this.isInvoice(this.doc_type_key)) return;
      this.expandedSections.einvoiceValidation = true;
      // The page keeps laying out (other accordions/cards render after this
      // tick), so a single scroll fires before the panel reaches its final
      // position. Re-scroll a few times until the layout settles.
      const scrollToPanel = () => {
        const panel = this.$refs.einvoicePanel as { $el?: HTMLElement } | undefined;
        const el =
          panel?.$el ||
          document.querySelector('[data-test="toggle-xrechnung-validation"]');
        el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
      };
      this.$nextTick(scrollToPanel);
      [250, 600, 1000].forEach((ms) => setTimeout(scrollToPanel, ms));
    },

    setDefaultValues () {
      // merge default values with this.model
      Object.assign(this.model, {
        [this.pdf_template]: false,
        [this.approval_stamp]: false,
        [this.ai_system_prompt]: '',
        [this.ai_assistant_prompt]: '',
        [this.approval_history]: false,
        [this.pdf_export_to_idm]: false,
        [this.duplicate_detection]: false,
        [this.skip_table_validation]: false,
        [this.approve_before_export]: false,
        [this.approve_before_export_v2]: false,
        [this.custom_validation_rules_enabled]: false,
        [this.transformation_rules_enabled]: false,
        [this.layout_selection_rules_enabled]: false,
        [this.duplicate_detection_fields]: '',
        [this.duplicate_invoice_detection]: false,
        [this.ignore_tax_free_line]: true,
        [this.disallow_export_of_duplicates]: false,
        [this.second_approval_before_export]: false,
        [this.duplicate_detection_interval]: '',
        [this.allow_multiple_export_configurations]: false,
        // E-Invoice validation (BOL-401 / BOL-413). Both default to
        // false so existing doc-types are unchanged on rollout — Org
        // admins must opt-in per doc-type via the toggle.
        [this.xrechnung_validation_enabled]: false,
        [this.xrechnung_supplier_notification_enabled]: false,
      });
    },

    async updateValue (attribute_key: string, attribute_value: any) {
      try {
          this.loading_data = true;
          await this.setAttribute(attribute_key, attribute_value);
          notify.success(this.$t('MSG_SAVE'));

          if ( attribute_key == this.duplicate_detection_interval && ['6 months', '1 year'].includes(attribute_value) ) {
            notify.warning(this.$t('duplicate_detection_interval_tooltip'));
          }
      } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
      } finally {
          this.loading_data = false;
      }
    },

    async setLayoutPreference(value: boolean){
      try {
          this.loading_data = true;
          const docType = this.$route.params.doc_type as string;
          const payload = { active: value, doc_type_key: docType } as dynamicObj;
          await formBuilderApiService.setLayoutManagementPreferences(payload);
          notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
      } finally {
          this.loading_data = false;
      }
    },

    async restoreDefault (attribute_key: string) {
      try {
          this.loading_data = true;

          const response = await docTypeApiService.deleteDocumentTypeAttribute(this.docTypeAttributes[attribute_key].id);
          if (response.success == false) {
              throw response;
          }

          await this.getDocTypeSettings();

          notify.success(this.$t('success'));
      } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          notify.error(msg);
          logError(err);
      } finally {
          this.loading_data = false;
      }
    },
    async openFormBuilder(layoutTypes: string) {
      if(this.formBuilderLoading) {
        return
      }

      const docType = this.$route.params.doc_type as string;
      if(!docType) {
        return
      }

      this.formBuilderLoading = true;

      try {
        await this.getLayoutTemplateID(docType, layoutTypes);

        let route = '/layout-builder/' + docType + '/' + layoutTypes;

        if (this.layout_template_id) {
          route += '?id=' + this.layout_template_id;
        }
        this.$router.push(route);
      } finally {
        this.formBuilderLoading = false;
      }

    },
    openCustomValidationRules() {
      const docType = this.$route.params.doc_type as string;
      if (!docType) {
        return;
      }
      this.$router.push('/settings/custom-validation-rules/' + docType);
    },
    openTransformationRules() {
      const docType = this.$route.params.doc_type as string;
      if (!docType) {
        return;
      }
      this.$router.push('/settings/transformation-rules/' + docType);
    },
    async getLayoutTemplateID (docType: string, layoutTypes: string) {

      try {
        // this.showLoading();
        const query_data = {} as dynamicObj;
        query_data['doc_type_key'] = docType;

        query_data['layout_type'] = layoutTypes;

        const response = await formBuilderApiService.getLayoutTemplates(query_data);
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }

        if(response.data && response.data[0]) {
          this.layout_template_id = response.data[0].id;
        }

      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },

    preparePdfExportTypeList() {
      // Values should match the exact keys of the PO table columns
      this.export_pdf_type_list = [
        {
          label: this.$t('default'),
          value: 'default'
        },
        {
          label: this.$t('original'),
          value: 'original'
        },
        {
          label: this.$t('PDF'),
          value: 'pdf'
        },
        {
          label: this.$t('PDFA'),
          value: 'pdfa'
        },
        {
          label: this.$t('PDFA-1'),
          value: 'pdfa-1'
        },
        {
          label: this.$t('PDFA-2'),
          value: 'pdfa-2'
        },
        {
          label: this.$t('PDFA-3'),
          value: 'pdfa-3'
        }
      ];
    },

    async getDocumentFields() {
      try {

        if(!this.doc_type_key) {
          return
        }

        this.fields_list = []
        const doc_field_resp = await decisionApiService.getDocumentTypeFields(this.doc_type_key)
        doc_field_resp.forEach((element: any) => {
          this.fields_list.push({ label: this.getLabelToDisplay(element), value: element.field_name });
        });
      }
      catch (error) {
        notify.error(error)
      }
      finally {
        this.hideLoading()
      }
    },
    formatePreferenceData() {
      if(this.model[this.duplicate_detection_fields]) {
        this.duplicateDetectionFields = this.model[this.duplicate_detection_fields].split(',');
      }
    },
    saveDuplicateDetectionFields(val : any) {

      this.model[this.duplicate_detection_fields] = this.duplicateDetectionFields.join(',');
      this.updateValue(this.duplicate_detection_fields, this.model[this.duplicate_detection_fields]);
    },
    prepareDuplicateDetectionIntervalOptions() {
      this.duplicateDetectionIntervalOptions = [
        {
          label: this.$t('one_month'),
          value: '1 month'
        },
        {
          label: this.$t('three_months'),
          value: '3 months'
        },
        {
          label: this.$t('six_months'),
          value: '6 months'
        },
        {
          label: this.$t('one_year'),
          value: '1 year'
        },
      ];
    },

    // Alternate Export Methods
    updateAlternateExportSettings(attribute_key: string, attribute_value: any) {
      this.model[this.doc_alternate_export_status] = '';
      this.model[this.doc_alternate_export_export_config] = '';

      this.updateValue(attribute_key, attribute_value);
      this.updateValue(this.doc_alternate_export_status, '');
      this.updateValue(this.doc_alternate_export_export_config, '');
    },

    initAlternateExportStatuses() {
      this.alternate_export_statuses_list = [];
      for (const [key, item_name] of Object.entries(
        this.alternate_export_statuses_all,
      )) {
        this.alternate_export_statuses_list.push({
          label: this.$t(item_name),
          value: item_name,
        });
      }

      this.alternate_export_statuses = this.alternate_export_statuses_list;
    },

    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.alternate_export_statuses = this.alternate_export_statuses_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.alternate_export_statuses =
          this.alternate_export_statuses_list.filter(
            (v: any) => v.label.toLowerCase().startsWith(needle) as string,
          );
      });
    },

    loadExportConfigurationsList() {
      this.export_configurations_all = [];

      for (const [key, item] of Object.entries(this.configurations)) {
        const config = item as dynamicObj;
        this.export_configurations_all.push({
          label: this.$t(config.title),
          value: config.id,
        });
      }

      this.export_configurations = this.export_configurations_all;
      this.export_config_name = this.export_configurations.find(
        (item: any) =>
          item.value == this.model[doc_alternate_export_export_config],
      );
    },

    filterExportConfigurationEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.export_configurations = this.export_configurations_all;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.export_configurations = this.export_configurations_all.filter(
          (v: any) => v.label.toLowerCase().startsWith(needle) as string,
        );
      });
    }
  },
  setup() {
    const doc_attribute_store = useDocAttributesStore();
    const { doc_type_key, model, loading_data, docTypeAttributes } = storeToRefs(doc_attribute_store);
    const { getDocTypeSettings, setAttribute } = doc_attribute_store;

    const doc_export_store = useDocExportStore();
    const { getExportConfigurations } = doc_export_store;
    const { configurations, processing } = storeToRefs(doc_export_store);

    return {
      setAttribute,
      getDocTypeSettings,
      getExportConfigurations,
      configurations,
      processing,
      export_pdf_type_list: ref([] as any),
      model,
      doc_type_key,
      loading_data,
      docTypeAttributes,
      fields_list: ref([] as any),
      layout_template_id: ref(''),
      duplicateDetectionFields: ref([] as any),
      duplicateDetectionIntervalOptions: ref([] as any),
      export_config_name: ref(''),
      export_configurations: ref([] as any),
      export_configurations_all: ref([] as any),
      alternate_export_statuses: ref([] as any),
      formBuilderLoading: ref(false),
    };
  },
});
</script>
<style scoped lang="scss">
.disabled-link {
  pointer-events: none;
  opacity: 0.5;
}

.settings-design-link {
  display: inline-flex;
  align-items: center;
  line-height: 1;
}

// E-Invoice Validation: clean 3-column grid (label / description / toggle).
// The shared `.settings-toggle-*` layout in app.scss is single-row by
// design, so two-line labels paired with multi-line descriptions
// produce visibly misaligned rows. Lokales Grid hier garantiert eine
// einheitliche Spaltenbreite über alle Zeilen.
.einvoice-toggle-row {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr) auto;
  align-items: start;
  gap: 1.25rem;
  padding: 0.85rem 1rem;
  border-radius: 0.5rem;
  transition: background 0.15s ease;

  & + .einvoice-toggle-row {
    border-top: 1px solid #eef2f6;
  }

  &:hover {
    background: rgba(0, 0, 0, 0.02);
  }
}

.einvoice-toggle-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--dashboard-text-color, #374151);
  line-height: 1.45;
  padding-top: 2px;
  word-break: break-word;
}

.einvoice-toggle-desc {
  font-size: 0.8125rem;
  color: #6b7280;
  line-height: 1.55;
  padding-top: 2px;
}

.einvoice-toggle-action {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-top: 2px;
}

@media (max-width: 720px) {
  .einvoice-toggle-row {
    grid-template-columns: 1fr auto;
    grid-template-areas:
      "label  toggle"
      "desc   desc";
    gap: 0.5rem 0.75rem;
  }

  .einvoice-toggle-label  { grid-area: label; }
  .einvoice-toggle-action { grid-area: toggle; }
  .einvoice-toggle-desc   { grid-area: desc; }
}

body.body--dark {
  .einvoice-toggle-label { color: #e4e4e4; }
  .einvoice-toggle-desc  { color: #a0a0a0; }
  .einvoice-toggle-row + .einvoice-toggle-row {
    border-top-color: rgba(255, 255, 255, 0.06);
  }
  .einvoice-toggle-row:hover { background: rgba(255, 255, 255, 0.03); }
}
</style>
